command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="24bb8722c06b302f6a6b9c00aad34293a38be0d0";$candidate="42453d5a3a914eb01b16cc5b28fb1f72e059014a";$branch="work/unc-network-copy-move-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UNC root-contract fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UNC root validation"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "UNC root candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-unc-root-"+$env:GITHUB_RUN_ID)
if(Test-Path $temp){Remove-Item $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "UNC root worktree add failed"}
 Set-Location $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "UNC root diff check failed"}
 & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
 if($LASTEXITCODE -ne 0){throw "UNC root FAST failed"}
 & .\app\winui\helper\build.cmd Debug
 if($LASTEXITCODE -ne 0){throw "UNC root helper Debug failed"}
 & .\tests\winui\m22\build.cmd Debug
 if($LASTEXITCODE -ne 0){throw "UNC root M22 Debug build failed"}
 $env:FLY_M22_CONFIG="Debug";$env:FLY_M22_LOOPBACK_ADMIN_SHARE="YES"
 & python -X utf8 .\tests\winui\m22\test_native.py
 if($LASTEXITCODE -ne 0){throw "UNC root M22 Debug native failed"}
 Write-Host "UNC_ROOT_FAST=PASS"
 Write-Host "UNC_ROOT_HELPER_DEBUG=PASS"
 Write-Host "UNC_ROOT_M22_DEBUG=PASS"
}finally{
 Remove-Item Env:FLY_M22_CONFIG -ErrorAction SilentlyContinue
 Remove-Item Env:FLY_M22_LOOPBACK_ADMIN_SHARE -ErrorAction SilentlyContinue
 Set-Location $repo
 if(Test-Path $temp){& git worktree remove --force $temp}
 & git worktree prune
}
